import{_ as s,o as a,c as i,ai as e}from"./chunks/framework.Ai2o9gNv.js";const t="/assets/image-20260130180814385.9nUD8vkN.png",l="/assets/image-20260130180834296.DqHj9YF9.png",r="/assets/image-20260130180851382.DHCTaHqB.png",o="/assets/image-20260130180912100.DyITjIg9.png",p="/assets/image-20260130180925757.BT5KGIPp.png",h="/assets/image-20260130181439344.Bbf9kF6D.png",c="/assets/image-20260130181922571.CGeRPKJt.png",f=JSON.parse('{"title":"春节马年祝福海报生成器 2026","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/春节马年祝福海报生成器-2026/春节马年祝福海报生成器-2026.md","filePath":"AI人工智能/春节马年祝福海报生成器-2026/春节马年祝福海报生成器-2026.md","lastUpdated":1769768742000,"__rawMarkdown":"# 春节马年祝福海报生成器 2026\\n\\n## 项目简介\\n\\n春节马年祝福海报生成器是一个基于 **HTML + CSS + Three.js** 开发的春节主题互动网站。\\n\\n用户只需输入姓名，即可生成精美的马年祝福海报，并支持下载分享。\\n\\n> 这是一个使用iflow+GML4.7 做的静态网站\\n>\\n> 体验地址：https://itcastwsy.github.io/iflow-game-2026/index.html\\n\\n## 效果\\n\\n直接上效果：\\n\\n![](assets/image-20260130180814385.png)\\n\\n---\\n\\n![](assets/image-20260130180834296.png)\\n\\n---\\n\\n刷新了会随机切换主题：\\n\\n![](assets/image-20260130180851382.png)\\n\\n---\\n\\n![](assets/image-20260130180912100.png)\\n\\n---\\n\\n![](assets/image-20260130180925757.png)\\n\\n---\\n\\n##  技术实现\\n\\n### 技术栈\\n- **iflow + GML4.7**\\n- **HTML5**：页面结构\\n- **CSS3**：动画效果、渐变、布局\\n- **Three.js**：3D背景动画\\n- **Canvas API**：海报绘制\\n\\n### 核心功能实现\\n\\n#### 1. Three.js 3D背景\\n- **粒子系统**：500个金色粒子在3D空间中旋转\\n- **3D灯笼**：5个红色灯笼悬浮在背景中，带有浮动动画\\n- **性能优化**：使用透明度和模糊效果，不影响前端性能\\n\\n#### 2. 海报生成系统\\n```\\n海报生成流程：\\n1. 用户输入姓名 → 2. 随机选择祝福词 → 3. 随机选择渐变背景\\n→ 4. 绘制装饰元素 → 5. 绘制马年主题 → 6. 添加祝福词 → 7. 渲染完成\\n```\\n\\n#### 3. 祝福词库设计\\n内置30条马年祝福语，采用模板替换机制：\\n```javascript\\nconst blessings = [\\n    \\"{name}祝福马年大吉！\\",\\n    \\"{name}祝您马年马到成功！\\",\\n    // ... 更多祝福词\\n];\\n```\\n\\n#### 4. Canvas绘制\\n- **渐变背景**：8种春节主题渐变色\\n- **装饰元素**：金色边框、角落花纹、红灯笼\\n- **文字渲染**：渐变色\\"马年\\"字样，带阴影效果\\n- **祝福词框**：半透明背景 + 金色边框\\n\\n## 开发流程\\n\\n1. 在空的目录内启动 **iflow**\\n\\n   > iflow -y \\n\\n2. 输入提示词\\n\\n   >  帮我使用html+css+threejs\\n   >       实现一个春节马年祝福词海报生成网站，打开网站提示让用户输入姓名，然后就结合姓名生成对应的 比如\\n   >       万少祝福马年大吉 等祝福词。  核心\\n   >       是随机生成好看的酷炫的海报图片，可以下载图片。请你梳理我的需求，和我确认无误后，再开始编码\\n\\n3. iflow 开始跑\\n\\n![image-20260130181439344](assets/image-20260130181439344.png)\\n\\n4. 得到网站\\n\\n![](assets/image-20260130181922571.png)\\n\\n\\n\\n"}'),g={name:"AI人工智能/春节马年祝福海报生成器-2026/春节马年祝福海报生成器-2026.md"};function d(m,n,u,b,k,_){return a(),i("div",null,[...n[0]||(n[0]=[e("",36)])])}const v=s(g,[["render",d]]);export{f as __pageData,v as default};
